 void startCamera(){status.setText("후면카메라 시작 중...");ListenableFuture<ProcessCameraProvider> f=ProcessCameraProvider.getInstance(this);f.addListener(()->{try{provider=f.get();Preview pr=new Preview.Builder().build();pr.setSurfaceProvider(preview.getSurfaceProvider());ImageAnalysis an=new ImageAnalysis.Builder().setBackpressureStrategy(ImageAnalysis.STRATEGY_KEEP_ONLY_LATEST).build();an.setAnalyzer(ex,this::analyze);provider.unbindAll();provider.bindToLifecycle(this,CameraSelector.DEFAULT_BACK_CAMERA,pr,an);status.setText("카메라 연결 완료. Blank를 ROI에 맞추세요.");}catch(Exception e){status.setText("카메라 오류: "+e.getMessage());}},ContextCompat.getMainExecutor(this));}
 void analyze(@NonNull ImageProxy im){try{long now=SystemClock.elapsedRealtime();if(now-lastFrame<250)return;lastFrame=now;ImageProxy.PlaneProxy[] ps=im.getPlanes();if(ps.length<3)return;int w=im.getWidth(),hh=im.getHeight(),sz=(int)(Math.min(w,hh)*.28),sx=(w-sz)/2,sy=(hh-sz)/2,step=Math.max(2,sz/70);ByteBuffer yb=ps[0].getBuffer(),ub=ps[1].getBuffer(),vb=ps[2].getBuffer();int yrs=ps[0].getRowStride(),yps=ps[0].getPixelStride(),urs=ps[1].getRowStride(),ups=ps[1].getPixelStride(),vrs=ps[2].getRowStride(),vps=ps[2].getPixelStride();long sr=0,sg=0,sb=0;int n=0;for(int y=sy;y<sy+sz;y+=step)for(int x=sx;x<sx+sz;x+=step){int yi=y*yrs+x*yps,ux=x/2,uy=y/2,ui=uy*urs+ux*ups,vi=uy*vrs+ux*vps;if(yi>=yb.limit()||ui>=ub.limit()||vi>=vb.limit())continue;int Y=yb.get(yi)&255,U=ub.get(ui)&255,V=vb.get(vi)&255,c=Math.max(0,Y-16),dd=U-128,e=V-128,R=cl((298*c+409*e+128)>>8),G=cl((298*c-100*dd-208*e+128)>>8),B=cl((298*c+516*dd+128)>>8);sr+=R;sg+=G;sb+=B;n++;}if(n==0)return;double R=sr/(double)n,G=sg/(double)n,B=sb/(double)n,I=switch(channel.getSelectedItemPosition()){case 0->R;case 1->G;case 2->B;default->.2126*R+.7152*G+.0722*B;};double A=Double.NaN,C=Double.NaN,rel=Double.NaN;if(!Double.isNaN(blank)&&blank>0&&I>0){A=-Math.log10(I/blank);if(!Double.isNaN(k)&&k>0){C=Math.max(0,A/k);double mx=num(maxC,0);if(mx>0)rel=C/mx*100;}}cur=new Reading(R,G,B,I,A,C,rel);Reading z=cur;runOnUiThread(()->show(z));}finally{im.close();}}
 void show(Reading z){rT.setText(f(z.r));gT.setText(f(z.g));bT.setText(f(z.b));aT.setText(Double.isNaN(z.a)?"-":String.format(Locale.US,"%.4f",z.a));cT.setText(Double.isNaN(z.c)?"-":String.format(Locale.US,"%.4f",z.c));}
 void blank(){if(cur==null){toast("측정값이 없습니다.");return;}blank=cur.i;k=Double.NaN;status.setText(String.format(Locale.US,"Blank 저장 완료 · I₀=%.2f",blank));}
 void standard(){if(cur==null||Double.isNaN(blank)){toast("먼저 Blank를 저장하세요.");return;}double sc=num(stdC,0),A=-Math.log10(cur.i/blank);if(!(sc>0&&A>0)){toast("표준용액 조건을 확인하세요.");return;}k=A/sc;status.setText(String.format(Locale.US,"표준 보정 완료 · k=%.5f",k));}
 void toggle(){if(auto){auto=false;h.removeCallbacks(autoRun);autoBtn.setText("자동 기록 시작");status.setText("자동 기록 중지");return;}auto=true;start=SystemClock.elapsedRealtime();autoBtn.setText("자동 기록 중지");record();h.postDelayed(autoRun,(long)(Math.max(1,num(interval,5))*1000));}
 final Runnable autoRun=new Runnable(){public void run(){if(!auto)return;record();h.postDelayed(this,(long)(Math.max(1,num(interval,5))*1000));}};
 void record(){if(cur==null){toast("측정값이 없습니다.");return;}if(start==0)start=SystemClock.elapsedRealtime();rows.add(new Row((SystemClock.elapsedRealtime()-start)/60000.0,num(ph,Double.NaN),cur));countT.setText(String.valueOf(rows.size()));}
