 void csv(){if(rows.isEmpty()){toast("저장할 데이터가 없습니다.");return;}String name="alginate_"+new SimpleDateFormat("yyyyMMdd_HHmmss",Locale.US).format(new Date())+".csv";ContentValues v=new ContentValues();v.put(MediaStore.Downloads.DISPLAY_NAME,name);v.put(MediaStore.Downloads.MIME_TYPE,"text/csv");v.put(MediaStore.Downloads.RELATIVE_PATH,Environment.DIRECTORY_DOWNLOADS+"/AlginateColorimeter");Uri u=getContentResolver().insert(MediaStore.Downloads.EXTERNAL_CONTENT_URI,v);if(u==null){toast("CSV 생성 실패");return;}StringBuilder s=new StringBuilder("No,Time_min,pH,R,G,B,Absorbance,Concentration,Release_percent\n");for(int i=0;i<rows.size();i++){Row r=rows.get(i);s.append(i+1).append(',').append(String.format(Locale.US,"%.4f",r.t)).append(',').append(Double.isNaN(r.ph)?"":String.format(Locale.US,"%.2f",r.ph)).append(',').append(String.format(Locale.US,"%.3f,%.3f,%.3f,",r.r,r.g,r.b)).append(Double.isNaN(r.a)?"":String.format(Locale.US,"%.6f",r.a)).append(',').append(Double.isNaN(r.c)?"":String.format(Locale.US,"%.6f",r.c)).append(',').append(Double.isNaN(r.rel)?"":String.format(Locale.US,"%.3f",r.rel)).append('\n');}try(OutputStream o=getContentResolver().openOutputStream(u)){o.write(new byte[]{(byte)0xEF,(byte)0xBB,(byte)0xBF});o.write(s.toString().getBytes(StandardCharsets.UTF_8));toast("Downloads/AlginateColorimeter 저장 완료");}catch(Exception e){toast("CSV 오류: "+e.getMessage());}}
 LinearLayout col(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;}LinearLayout row(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.HORIZONTAL);return l;}TextView txt(String s,float z,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(bold?TXT:MUTED);if(bold)t.setTypeface(null,1);return t;}void panel(View v){android.graphics.drawable.GradientDrawable g=new android.graphics.drawable.GradientDrawable();g.setColor(CARD);g.setCornerRadius(d(14));v.setBackground(g);v.setPadding(d(10),d(10),d(10),d(10));}TextView metric(LinearLayout r,String name){LinearLayout b=col();panel(b);b.addView(txt(name,11,false));TextView v=txt("-",21,true);b.addView(v);weight(r,b);return v;}EditText edit(String hint,String val){EditText e=new EditText(this);e.setHint(hint);e.setText(val);e.setTextColor(TXT);e.setHintTextColor(MUTED);e.setInputType(android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL);return e;}Button btn(String s){Button b=new Button(this);b.setText(s);b.setAllCaps(false);return b;}void weight(LinearLayout p,View v){LinearLayout.LayoutParams q=new LinearLayout.LayoutParams(0,-2,1);q.setMargins(d(3),d(4),d(3),d(4));p.addView(v,q);}LinearLayout.LayoutParams top(int x){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,d(x),0,0);return p;}int d(int x){return(int)(x*getResources().getDisplayMetrics().density+.5f);}double num(EditText e,double x){try{return Double.parseDouble(e.getText().toString());}catch(Exception q){return x;}}String f(double x){return String.format(Locale.US,"%.1f",x);}static int cl(int x){return Math.max(0,Math.min(255,x));}void toast(String x){Toast.makeText(this,x,Toast.LENGTH_SHORT).show();}
